"""Writes src/lib/brands.ts: brand and tech logos from Simple Icons (CC0) as SVG path data.

Usage: python3 -I tools/brands.py  (SVGs are read from public/img/logos/*.svg)
"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
lines = []
for f in sorted((ROOT / 'public/img/logos').glob('*.svg')):
    d = re.search(r'<path d="([^"]+)"', f.read_text())
    if d:
        lines.append(f"  '{f.stem}': '{d.group(1)}',")
(ROOT / 'src/lib/brands.ts').write_text(
    '// Generated by tools/brands.py from Simple Icons (CC0). Do not edit by hand.\n'
    '// Each value is SVG path data in a 24 unit box.\n'
    'export const brands = {\n' + '\n'.join(lines) + '\n} as const;\n\n'
    'export type BrandName = keyof typeof brands;\n')
print(len(lines), 'brand logos written')
